-- PostgreSQL 18.6 is the oracle for atomic fan-out and savepoint semantics.
CREATE TABLE atomic_trace(relation_name text);
CREATE FUNCTION atomic_trace_truncate() RETURNS trigger LANGUAGE plpgsql AS
$$BEGIN INSERT INTO atomic_trace VALUES(TG_TABLE_NAME); RETURN NULL; END$$;
CREATE TABLE atomic_root(id int);
CREATE TABLE atomic_left() INHERITS (atomic_root);
CREATE TABLE atomic_right() INHERITS (atomic_root);
CREATE TABLE atomic_diamond(PRIMARY KEY(id)) INHERITS (atomic_left, atomic_right);
CREATE TABLE atomic_reference(id int REFERENCES atomic_diamond(id));
INSERT INTO atomic_root VALUES(1);
INSERT INTO atomic_left VALUES(2);
INSERT INTO atomic_right VALUES(3);
INSERT INTO atomic_diamond VALUES(4);
INSERT INTO atomic_reference VALUES(4);
CREATE TRIGGER atomic_root_trace AFTER TRUNCATE ON atomic_root FOR EACH STATEMENT EXECUTE FUNCTION atomic_trace_truncate();
CREATE TRIGGER atomic_left_trace AFTER TRUNCATE ON atomic_left FOR EACH STATEMENT EXECUTE FUNCTION atomic_trace_truncate();
CREATE TRIGGER atomic_right_trace AFTER TRUNCATE ON atomic_right FOR EACH STATEMENT EXECUTE FUNCTION atomic_trace_truncate();
CREATE TRIGGER atomic_diamond_trace AFTER TRUNCATE ON atomic_diamond FOR EACH STATEMENT EXECUTE FUNCTION atomic_trace_truncate();
CREATE TRIGGER atomic_reference_trace AFTER TRUNCATE ON atomic_reference FOR EACH STATEMENT EXECUTE FUNCTION atomic_trace_truncate();
TRUNCATE atomic_root;
SELECT count(*) FROM atomic_root;
BEGIN;
SAVEPOINT before_inheritance_truncate;
TRUNCATE atomic_root CASCADE;
SELECT count(*) FROM atomic_root;
SELECT relation_name FROM atomic_trace ORDER BY relation_name;
ROLLBACK TO before_inheritance_truncate;
SELECT count(*) FROM atomic_root;
SELECT count(*) FROM atomic_trace;
TRUNCATE atomic_root, atomic_reference;
COMMIT;
SELECT relation_name FROM atomic_trace ORDER BY relation_name;
SELECT count(*) FROM atomic_root;
DELETE FROM atomic_trace;

CREATE TABLE atomic_partition(id int) PARTITION BY RANGE(id);
CREATE TABLE atomic_partition_middle PARTITION OF atomic_partition
  FOR VALUES FROM(0) TO(20) PARTITION BY RANGE(id);
CREATE TABLE atomic_partition_low PARTITION OF atomic_partition_middle FOR VALUES FROM(0) TO(10);
CREATE TABLE atomic_partition_high PARTITION OF atomic_partition_middle FOR VALUES FROM(10) TO(20);
CREATE TRIGGER atomic_partition_trace AFTER TRUNCATE ON atomic_partition
  FOR EACH STATEMENT EXECUTE FUNCTION atomic_trace_truncate();
INSERT INTO atomic_partition VALUES(1), (11);
TRUNCATE atomic_partition;
SELECT count(*) FROM atomic_partition;
SELECT count(*) FROM atomic_partition_low;
SELECT count(*) FROM atomic_partition_high;
SELECT relation_name FROM atomic_trace;

