COMMIT;
SHOW application_name;
SELECT count(*), max(id) FROM atomic_savepoint_rows;

CREATE TABLE atomic_deferred_parent(id int PRIMARY KEY);
CREATE TABLE atomic_deferred_child(
  id int CONSTRAINT atomic_deferred_unique UNIQUE DEFERRABLE INITIALLY DEFERRED,
  parent_id int CONSTRAINT atomic_deferred_foreign REFERENCES atomic_deferred_parent(id) DEFERRABLE INITIALLY DEFERRED,
  body text
);
CREATE TABLE atomic_deferred_audit(id int);
CREATE FUNCTION atomic_deferred_trace() RETURNS trigger LANGUAGE plpgsql AS
$$BEGIN INSERT INTO atomic_deferred_audit VALUES(NEW.id); RETURN NULL; END$$;
CREATE CONSTRAINT TRIGGER atomic_deferred_trigger AFTER INSERT ON atomic_deferred_child
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION atomic_deferred_trace();
BEGIN;
INSERT INTO atomic_deferred_child SELECT i, 1, repeat('x', 512) FROM generate_series(1, 300) AS g(i);
INSERT INTO atomic_deferred_parent VALUES(1);
SELECT count(*) FROM atomic_deferred_audit;
SAVEPOINT before_deferred_validation;
SET CONSTRAINTS atomic_deferred_unique, atomic_deferred_foreign, atomic_deferred_trigger IMMEDIATE;
SELECT count(*) FROM atomic_deferred_audit;
ROLLBACK TO before_deferred_validation;
SELECT count(*) FROM atomic_deferred_audit;
COMMIT;
SELECT count(*), min(octet_length(body)) FROM atomic_deferred_child;
SELECT count(*), count(DISTINCT id) FROM atomic_deferred_audit;

