CREATE FUNCTION atomic_deferred_delete_trace() RETURNS trigger LANGUAGE plpgsql AS
$$BEGIN INSERT INTO atomic_deferred_audit VALUES(OLD.id); RETURN NULL; END$$;
CREATE CONSTRAINT TRIGGER atomic_deferred_delete_trigger AFTER DELETE ON atomic_deferred_child
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION atomic_deferred_delete_trace();
DELETE FROM atomic_deferred_audit;
BEGIN;
SAVEPOINT before_deferred_delete;
DELETE FROM atomic_deferred_child;
ROLLBACK TO before_deferred_delete;
SELECT count(*), min(octet_length(body)) FROM atomic_deferred_child;
DELETE FROM atomic_deferred_child;
SELECT count(*) FROM atomic_deferred_audit;
SAVEPOINT before_old_row_validation;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT count(*) FROM atomic_deferred_audit;
ROLLBACK TO before_old_row_validation;
SELECT count(*) FROM atomic_deferred_audit;
COMMIT;
SELECT count(*) FROM atomic_deferred_child;
SELECT count(*), count(DISTINCT id) FROM atomic_deferred_audit;

DROP TRIGGER atomic_root_trace ON atomic_root;
DROP TRIGGER atomic_left_trace ON atomic_left;
DROP TRIGGER atomic_right_trace ON atomic_right;
DROP TRIGGER atomic_diamond_trace ON atomic_diamond;
DROP TRIGGER atomic_reference_trace ON atomic_reference;
DROP TRIGGER atomic_partition_trace ON atomic_partition;
DROP TRIGGER atomic_deferred_trigger ON atomic_deferred_child;
DROP TRIGGER atomic_deferred_delete_trigger ON atomic_deferred_child;
DROP FUNCTION atomic_trace_truncate();
DROP FUNCTION atomic_deferred_trace();
DROP FUNCTION atomic_deferred_delete_trace();
